// Some portions generated by Claude
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions} from './graph-layout-engine.ts';
import {graphNodeSize} from './graph-geometry.ts';
import {layoutNodeFixed} from './graph-layout-topology.ts';
import {segmentIntersectsBounds} from './graph-curve-collision.ts';
import {SpatialGrid, type Bounds} from './spatial-grid.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';

const segmentBounds = (a: PointerPosition, b: PointerPosition): Bounds =>
  ({minX: Math.min(a.x, b.x), minY: Math.min(a.y, b.y), maxX: Math.max(a.x, b.x), maxY: Math.max(a.y, b.y)});
const query = (index: SpatialGrid, b: Bounds) => index.search(b.minX, b.minY, b.maxX, b.maxY);
const cross = (a: PointerPosition, b: PointerPosition, c: PointerPosition) => (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
const crossing = (a: PointerPosition, b: PointerPosition, c: PointerPosition, d: PointerPosition) =>
  cross(a, b, c) * cross(a, b, d) < -1e-6 && cross(c, d, a) * cross(c, d, b) < -1e-6;

/** Bounded coordinate descent after topology placement, not another force run.
 * Only affected edges are scored, using dynamic rectangle indexes. Each move
 * must preserve card clearance, pins and group extents, and may worsen neither
 * obstruction count nor crossing count. Clear arrangements remain untouched.
 * The deterministic work cap bounds dense worst cases independently of CPU.
 */
export function improveLayoutReadability(graph: Graph, positions: Map<string, PointerPosition>,
  options: LayoutOptions = {}, groups: readonly (readonly number[])[] = []) {
  const stats = {moves: 0, checks: 0, capped: false};
  if (graph.nodes.length > 1500 || graph.edges.length > 4000) return stats;
  const nodes = graph.nodes.map(n => ({...positions.get(n.id)!, ...options.nodeSizes?.get(n.id) ?? graphNodeSize(n), fixed: layoutNodeFixed(n, options)}));
  const initial = nodes.map(n => ({x: n.x, y: n.y}));
  const ids = new Map(graph.nodes.map((n, i) => [n.id, i]));
  const edges: [number, number][] = [], pairs = new Set<string>(), incident = nodes.map(() => new Set<number>());
  for (const e of graph.edges) {
    const a = ids.get(e.source), b = ids.get(e.target);
    if (a === undefined || b === undefined || a === b) continue;
    const key = a < b ? `${a}:${b}` : `${b}:${a}`;
    if (pairs.has(key)) continue;
    pairs.add(key); incident[a].add(edges.length); incident[b].add(edges.length); edges.push([a, b]);
  }
  // A pure fan has no non-adjacent edge pair. Do not repeatedly search its
  // overlapping hub-centered edge boxes just to reject every candidate.
  const pureFan = incident.some(list => list.size === edges.length);
  const bounds = (i: number, paddingX = 7, paddingY = paddingX): Bounds => {
    const n = nodes[i]; return {minX: n.x - n.width / 2 - paddingX, minY: n.y - n.height / 2 - paddingY,
      maxX: n.x + n.width / 2 + paddingX, maxY: n.y + n.height / 2 + paddingY};
  };
  const nodeIndex = new SpatialGrid(256), edgeIndex = new SpatialGrid(256);
  nodes.forEach((_, i) => nodeIndex.insert(bounds(i, gap.nodeGapX / 2, gap.nodeGapY / 2)));
  edges.forEach(([a, b]) => edgeIndex.insert(segmentBounds(nodes[a], nodes[b])));
  const regions: (Bounds | undefined)[] = nodes.map(() => undefined);
  for (const group of groups) {
    if (group.length < 2) continue;
    const boxes = group.map(i => bounds(i, 0));
    const region = {minX: Math.min(...boxes.map(b => b.minX)), minY: Math.min(...boxes.map(b => b.minY)),
      maxX: Math.max(...boxes.map(b => b.maxX)), maxY: Math.max(...boxes.map(b => b.maxY))};
    group.forEach(i => {regions[i] = region;});
  }
  const budget = 4_000_000;
  const score = (id: number, collect = false) => {
    let obstructions = 0, crossings = 0, length = 0;
    const blockingEdges: number[] = [], own = bounds(id);
    for (const ei of query(edgeIndex, own)) {
      if (incident[id].has(ei)) continue;
      const [a, b] = edges[ei]; stats.checks++;
      if (segmentIntersectsBounds(nodes[a], nodes[b], own)) {obstructions++; if (collect) blockingEdges.push(ei);}
    }
    for (const ei of incident[id]) {
      const [a, b] = edges[ei], edgeBox = segmentBounds(nodes[a], nodes[b]);
      length += Math.hypot(nodes[a].x - nodes[b].x, nodes[a].y - nodes[b].y);
      for (const ni of query(nodeIndex, edgeBox)) {
        if (ni === a || ni === b) continue;
        stats.checks++;
        if (segmentIntersectsBounds(nodes[a], nodes[b], bounds(ni))) obstructions++;
      }
      for (const other of pureFan ? [] : query(edgeIndex, edgeBox)) {
        if (incident[id].has(other)) continue;
        const [c, d] = edges[other];
        if (a === c || a === d || b === c || b === d) continue;
        stats.checks++;
        if (crossing(nodes[a], nodes[b], nodes[c], nodes[d])) crossings++;
      }
    }
    return {obstructions, crossings, length, blockingEdges};
  };
  const legal = (id: number) => {
    const b = bounds(id, gap.nodeGapX / 2 - .005, gap.nodeGapY / 2 - .005), region = regions[id];
    if (region) {
      const actual = bounds(id, 0);
      if (actual.minX < region.minX - .01 || actual.maxX > region.maxX + .01 ||
          actual.minY < region.minY - .01 || actual.maxY > region.maxY + .01) return false;
    }
    return !query(nodeIndex, b).some(i => i !== id);
  };
  const radius = options.refine || options.incremental || options.localNodeIds?.size ? 240 : 340;
  for (let pass = 0; pass < 3; pass++) {
    const order: {id: number; pressure: number}[] = [];
    for (let i = 0; i < nodes.length && stats.checks <= budget; i++) {
      const n = nodes[i];
      // Keep high-degree backbone centers stable; repair the cheaper leaves
      // and their routes. Scoring every hub incident edge at every probe is
      // both expensive and disruptive to the neighborhood arrangement.
      if (n.fixed || incident[i].size > 24) continue;
      const s = score(i);
      if (s.obstructions || s.crossings) order.push({id: i, pressure: (s.obstructions * 4 + s.crossings) / Math.sqrt(1 + incident[i].size)});
    }
    order.sort((a, b) => b.pressure - a.pressure || a.id - b.id);
    let moved = false;
    for (const {id} of order) {
      if (stats.checks > budget) {stats.capped = true; break;}
      const n = nodes[id], origin = {x: n.x, y: n.y}, before = score(id, true);
      if (!before.obstructions && !before.crossings) continue;
      const candidates: PointerPosition[] = [];
      // Project a blocking card to either side of each obstructed segment.
      for (const ei of before.blockingEdges.slice(0, 12)) {
        const [a, b] = edges[ei], dx = nodes[b].x - nodes[a].x, dy = nodes[b].y - nodes[a].y, length = Math.hypot(dx, dy);
        if (!length) continue;
        const nx = -dy / length, ny = dx / length, signed = (n.x - nodes[a].x) * nx + (n.y - nodes[a].y) * ny;
        const support = Math.abs(nx) * n.width / 2 + Math.abs(ny) * n.height / 2 + 12;
        for (const side of [-1, 1]) {const delta = side * support - signed; candidates.push({x: n.x + nx * delta, y: n.y + ny * delta});}
      }
      for (const r of [56, 112, 224]) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1], [.707, .707], [.707, -.707], [-.707, .707], [-.707, -.707]]) {
        candidates.push({x: n.x + r * dx, y: n.y + r * dy});
      }
      let best = before, bestPoint = origin, bestMovement = Infinity;
      for (const candidate of candidates) {
        const displacement = Math.hypot(candidate.x - initial[id].x, candidate.y - initial[id].y);
        if (displacement > radius) continue;
        n.x = candidate.x; n.y = candidate.y;
        if (!legal(id)) continue;
        const s = score(id), movement = Math.hypot(n.x - origin.x, n.y - origin.y);
        if (s.obstructions > before.obstructions || s.crossings > before.crossings ||
            (s.obstructions === before.obstructions && s.crossings === before.crossings) || s.length > before.length * 1.18 + 100) continue;
        const cost = s.obstructions * 4 + s.crossings, bestCost = best.obstructions * 4 + best.crossings;
        if (cost < bestCost || cost === bestCost && movement < bestMovement) {best = s; bestPoint = candidate; bestMovement = movement;}
        if (stats.checks > budget) break;
      }
      n.x = bestPoint.x; n.y = bestPoint.y;
      if (bestPoint === origin) continue;
      nodeIndex.update(id, bounds(id, gap.nodeGapX / 2, gap.nodeGapY / 2));
      for (const ei of incident[id]) {const [a, b] = edges[ei]; edgeIndex.update(ei, segmentBounds(nodes[a], nodes[b]));}
      stats.moves++; moved = true;
    }
    if (!moved || stats.capped) break;
  }
  nodes.forEach((n, i) => positions.set(graph.nodes[i].id, {x: n.x, y: n.y}));
  return stats;
}
